class Solution {
public:
    int findSpecialInteger(vector<int>& arr) {
        int n = arr.size();
        for (int i : {n / 4, n / 2, 3 * n / 4}) {
            int x = arr[i];
            auto lo = lower_bound(arr.begin(), arr.end(), x);
            auto hi = upper_bound(arr.begin(), arr.end(), x);
            if (hi - lo > n / 4) return x;
        }
        return arr[0];
    }
};
